#pragma once

#include <cstdint>

// Unicode data for the regular expression engine: general categories, scripts and simple case
// mappings for the whole code space, generated by tools/gen_regex_unicode.py.
namespace ntregex {

constexpr int kCategoryCount = 30;

// Indexes into kCategoryNames; the order is that of the generated tables.
enum Category : std::uint8_t {
    Cc, Cf, Cn, Co, Cs, Ll, Lm, Lo, Lt, Lu, Mc, Me, Mn, Nd, Nl,
    No, Pc, Pd, Pe, Pf, Pi, Po, Ps, Sc, Sk, Sm, So, Zl, Zp, Zs
};

constexpr std::uint32_t catBit(Category c) { return std::uint32_t(1) << c; }
constexpr std::uint32_t kMaskL = catBit(Ll) | catBit(Lm) | catBit(Lo) | catBit(Lt) | catBit(Lu);
constexpr std::uint32_t kMaskM = catBit(Mc) | catBit(Me) | catBit(Mn);
constexpr std::uint32_t kMaskN = catBit(Nd) | catBit(Nl) | catBit(No);
constexpr std::uint32_t kMaskP = catBit(Pc) | catBit(Pd) | catBit(Pe) | catBit(Pf) | catBit(Pi) | catBit(Po) | catBit(Ps);
constexpr std::uint32_t kMaskS = catBit(Sc) | catBit(Sk) | catBit(Sm) | catBit(So);
constexpr std::uint32_t kMaskZ = catBit(Zl) | catBit(Zp) | catBit(Zs);
constexpr std::uint32_t kMaskC = catBit(Cc) | catBit(Cf) | catBit(Cn) | catBit(Co) | catBit(Cs);

struct CategoryRun {
    char32_t start;
    std::uint8_t category;
};
struct CaseRange {
    char32_t lo;
    char32_t hi;
    std::int32_t delta;
    std::uint8_t stride;
};
struct ScriptName {
    const char *name;
    int id;
};
struct ScriptRun {
    char32_t start;
    std::uint8_t script;
};

extern const char *const kCategoryNames[kCategoryCount];
extern const CategoryRun kCategoryRuns[];
extern const int kCategoryRunCount;
extern const CaseRange kLowerRanges[];
extern const int kLowerRangeCount;
extern const CaseRange kUpperRanges[];
extern const int kUpperRangeCount;
extern const ScriptName kScriptNames[];
extern const int kScriptNameCount;
extern const ScriptRun kScriptRuns[];
extern const int kScriptRunCount;
extern const int kUnknownScript;

Category categoryOf(char32_t c);
int scriptOf(char32_t c);
// Returns the script id for a normalized (lower-case, no separators) name, or -1.
int scriptByName(const char *normalized);
char32_t toLowerSimple(char32_t c);
char32_t toUpperSimple(char32_t c);
// The canonical representative of a case-equivalence class, used for caseless comparison.
char32_t foldCase(char32_t c);

bool isUnicodeWordChar(char32_t c);
bool isUnicodeSpace(char32_t c);

} // namespace ntregex
